408	    @Transactional
409	    public Sheet set(String sheetId, String user, Dated<BigDecimal> limit, Dated<BigDecimal> floor,
410	            Dated<Integer> terms, Dated<BigDecimal> latePct, boolean changePolicy, LocalDate policyDate,
411	            boolean changeNumbering, LocalDate numberingFrom, Dated<BigDecimal> cap,
412	            Map<String, Dated<Integer>> gradeTerms, Map<String, Dated<Integer>> gradeGraces,
413	            Dated<BigDecimal> proofThreshold, Map<String, Dated<BigDecimal>> gradeProofThresholds,
414	            Dated<BigDecimal> noteThreshold, Dated<BigDecimal> reviewThreshold, Map<String, String> permissions,
415	            boolean changeGrace, Integer graceDays, boolean changeEntry, LocalDate entryDate,
416	            boolean changePot, BigDecimal pot, boolean changeParent, String parent,
417	            Integer fiscalStartMonth, boolean changeAlert, BigDecimal alertThreshold, Dated<String> rounding,
418	            boolean changeEscalate, Integer escalateAfter, boolean changeReviewSla, Integer reviewSla,
419	            boolean changeProofKinds, String proofKinds) {
420	        roles.refuseViewer(sheetId, user);
421	        Sheet sheet = sheets.load(sheetId, user);
422	        if (changeParent && parent != null) {
423	            if (parent.equals(sheetId)) {
424	                throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A sheet cannot be its own parent.");
425	            }
426	            if (!sheetStore.existsById(parent)) {
427	                throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "No sheet " + parent + " has been loaded.");
428	            }
429	            if (rateChain.wouldLoop(sheetId, parent)) {
430	                throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Sheet " + parent + " has this sheet as an ancestor.");
431	            }
432	        }
433	        if (rounding != null && rounding.value() != null && !Sheet.ROUNDING_MODES.contains(rounding.value())) {
434	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The rounding mode is half-up or half-even.");
435	        }
436	        if (fiscalStartMonth != null && (fiscalStartMonth < 1 || fiscalStartMonth > 12)) {
437	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The fiscal start month is 1 to 12.");
438	        }
439	        if (limit != null) {
440	            sheet = record(sheet, user, CLERK_LIMIT, limit.value(), limit.from(), text(limit.value()), false);
441	        }
442	        if (floor != null) {
443	            sheet = record(sheet, user, FLOOR, floor.value(), floor.from(), text(floor.value()), true);
444	        }
445	        if (terms != null) {
446	            sheet = record(sheet, user, TERMS, BigDecimal.valueOf(terms.value()), terms.from(),
447	                    String.valueOf(terms.value()), false);
448	        }
449	        if (latePct != null) {
