462	        }
463	        if (changeNumbering) {
464	            sheet.setPeriodNumberingFrom(numberingFrom);
465	            sheet = sheetStore.saveAndFlush(sheet);
466	            audit.recordOnCommit(changed(sheetId, user, PERIOD_NUMBERING_FROM,
