483	            sheet = record(sheet, user, PROOF_THRESHOLD, proofThreshold.value(), proofThreshold.from(),
484	                    text(proofThreshold.value()), false);
485	        }
486	        for (Map.Entry<String, Dated<BigDecimal>> e : new TreeMap<>(gradeProofThresholds).entrySet()) {
487	            Dated<BigDecimal> t = e.getValue();
488	            sheet = record(sheet, user, GRADE_PROOF_THRESHOLD + e.getKey(), t.value(), t.from(), text(t.value()), false);
489	        }
490	        if (noteThreshold != null) {
491	            sheet = record(sheet, user, NOTE_THRESHOLD, noteThreshold.value(), noteThreshold.from(),
492	                    text(noteThreshold.value()), false);
493	        }
494	        if (reviewThreshold != null) {
495	            sheet = record(sheet, user, REVIEW_THRESHOLD, reviewThreshold.value(), reviewThreshold.from(),
496	                    text(reviewThreshold.value()), false);
497	        }
498	        for (Map.Entry<String, String> e : permissions.entrySet()) {
499	            sheet.setPermission(e.getKey(), e.getValue());
500	            sheet = sheetStore.saveAndFlush(sheet);
501	            audit.recordOnCommit(changed(sheetId, user, PERMISSION + e.getKey(), e.getValue()));
502	        }
503	        if (changeGrace) {
504	            sheet.setGraceDays(graceDays);
