553	    /**
554	     * Record a setting's value from a from-date (null: the sheet's today) and audit it; when it
555	     * {@code moves} the figures, the figures that move are recorded too.
556	     */
557	    private Sheet record(Sheet sheet, String user, String key, BigDecimal value, LocalDate from, String text,
558	            boolean moves) {
559	        String sheetId = sheet.getId();
560	        RollupService.Snapshot before = moves ? rollup.snapshot(sheetId) : null;
561	        sheet.record(key, from != null ? from : sheet.getToday(), value);
562	        Sheet saved = sheetStore.saveAndFlush(sheet);
563	        audit.recordOnCommit(changed(sheetId, user, key, text) + (from != null ? " from=" + from : ""));
564	        if (moves) {
565	            rollup.recordChanges(sheetId, user, before);
566	        }
567	        return saved;
568	    }
569	
570	    private static String changed(String sheetId, String user, String key, String value) {
571	        return "SETTING_CHANGED sheet=" + sheetId + " by=" + user + " key=" + key + " value=" + value;
572	    }
573	
574	    /** A limit with two decimals, or blank for none. */
575	    public static String text(BigDecimal limit) {
576	        return limit == null ? "" : limit.setScale(2, RoundingMode.UNNECESSARY).toPlainString();
577	    }
